import dlaln2 = require( './index' );


// TESTS //

// The function returns a Float64Array...
{
	const A = new Float64Array( 4 );
	const B = new Float64Array( 2 );
	const X = new Float64Array( 2 );
	const scale = new Float64Array( 1 );
	const xnorm = new Float64Array( 1 );
	const info = new Int32Array( 1 );
	dlaln2( 'row-major', 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 2, 1.0, 1.0, B, 1, 0.5, 0.0, X, 1, scale, xnorm, info ); // $ExpectType Float64Array
}

// The compiler throws an error if the function is provided a first argument which is not a valid layout...
{
	const A = new Float64Array( 4 );
	const B = new Float64Array( 2 );
	const X = new Float64Array( 2 );
	const scale = new Float64Array( 1 );
	const xnorm = new Float64Array( 1 );
	const info = new Int32Array( 1 );
	dlaln2( 5, 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 2, 1.0, 1.0, B, 1, 0.5, 0.0, X, 1, scale, xnorm, info ); // $ExpectError
	dlaln2( true, 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 2, 1.0, 1.0, B, 1, 0.5, 0.0, X, 1, scale, xnorm, info ); // $ExpectError
	dlaln2( false, 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 2, 1.0, 1.0, B, 1, 0.5, 0.0, X, 1, scale, xnorm, info ); // $ExpectError
	dlaln2( null, 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 2, 1.0, 1.0, B, 1, 0.5, 0.0, X, 1, scale, xnorm, info ); // $ExpectError
	dlaln2( void 0, 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 2, 1.0, 1.0, B, 1, 0.5, 0.0, X, 1, scale, xnorm, info ); // $ExpectError
	dlaln2( [], 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 2, 1.0, 1.0, B, 1, 0.5, 0.0, X, 1, scale, xnorm, info ); // $ExpectError
	dlaln2( {}, 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 2, 1.0, 1.0, B, 1, 0.5, 0.0, X, 1, scale, xnorm, info ); // $ExpectError
	dlaln2( ( x: number ): number => x, 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 2, 1.0, 1.0, B, 1, 0.5, 0.0, X, 1, scale, xnorm, info ); // $ExpectError
}

